//! Parity with an undated sequence: the parity cohort with one member of the
//! static giant component renamed so that it has no collection date
//! (`tests/fixtures/parity_undated/`, generated by
//! `scripts/regen_parity_undated.py`).
//!
//! `validation/run_danno.py` drops undated sequences before DANNO and before
//! its static arm (`static_0.015_on_dated_subset`). The golden values are its
//! output on this file (fed `tn93 -t 1.0 -a RMYSKB` distances), plus
//! `trace50.chin.ChinEstimator(1.5)` on the dated sample size. The distance
//! matrix is the parity fixture's: renaming a header changes no distance, and
//! the generator checks that tn93 gives the same rows on the renamed file.

use std::collections::{BTreeMap, BTreeSet};

use serde_json::Value;
use trace50::{
    run_trace50, run_trace50_with_matrix, Alignment, Trace50Config, VisualizationDossier,
};

const FASTA: &str = include_str!("fixtures/parity_undated/subset_undated.fasta");
const GOLDEN: &str = include_str!("fixtures/parity_undated/golden.json");
const DISTANCES: &str = include_str!("fixtures/parity/golden_distances.csv");
const PARITY_GOLDEN: &str = include_str!("fixtures/parity/golden.json");

/// CHIN is closed-form in (n, E), so identical inputs give identical values.
const EXACT_REL_TOL: f64 = 1e-9;

type Pair = (String, String);
type Partition = BTreeSet<BTreeSet<String>>;

fn pair(a: &str, b: &str) -> Pair {
    if a <= b {
        (a.to_string(), b.to_string())
    } else {
        (b.to_string(), a.to_string())
    }
}

fn rel_close(got: f64, want: f64, tol: f64) -> bool {
    if want == 0.0 {
        got.abs() <= tol
    } else {
        ((got - want) / want).abs() <= tol
    }
}

fn golden_matrix(n: usize) -> Vec<f64> {
    let mut m = vec![f64::NAN; n * n];
    for i in 0..n {
        m[i * n + i] = 0.0;
    }
    for line in DISTANCES.lines().skip(1) {
        let f: Vec<&str> = line.split(',').collect();
        let (i, j): (usize, usize) = (f[0].parse().unwrap(), f[1].parse().unwrap());
        let d: f64 = f[2].parse().unwrap();
        m[i * n + j] = d;
        m[j * n + i] = d;
    }
    m
}

fn partition(v: &Value) -> Partition {
    v.as_array()
        .unwrap()
        .iter()
        .map(|c| {
            c.as_array()
                .unwrap()
                .iter()
                .map(|x| x.as_str().unwrap().to_string())
                .collect()
        })
        .collect()
}

fn dossier_partition(
    d: &VisualizationDossier,
    label: impl Fn(&trace50::visualization::DossierNode) -> usize,
) -> Partition {
    let mut by: BTreeMap<usize, BTreeSet<String>> = BTreeMap::new();
    for node in &d.nodes {
        let c = label(node);
        if c > 0 {
            by.entry(c).or_default().insert(node.id.clone());
        }
    }
    by.into_values().collect()
}

/// run_danno.py's defaults, as recorded in the parity golden file.
fn config() -> Trace50Config {
    let pg: Value = serde_json::from_str(PARITY_GOLDEN).unwrap();
    let p = &pg["params"];
    let f = |k: &str| p[k].as_f64().unwrap();
    Trace50Config {
        mu: f("mu"),
        tau_bar: f("tau_bar"),
        omega: f("omega"),
        fdr_threshold: f("fdr"),
        max_delta_t: f("max_delta_t"),
        prior_odds: f("prior_odds"),
        static_distance_threshold: pg["static_threshold"].as_f64().unwrap(),
        r0: pg["chin"]["r0"].as_f64().unwrap(),
        ..Trace50Config::default()
    }
}

fn assert_matches(label: &str, d: &VisualizationDossier) {
    let g: Value = serde_json::from_str(GOLDEN).unwrap();
    let undated = g["renamed"]["to"].as_str().unwrap();

    assert_eq!(
        d.metadata.num_sequences as u64,
        g["n_sequences"].as_u64().unwrap()
    );
    assert_eq!(
        (d.metadata.num_sequences - d.metadata.num_undated) as u64,
        g["n_dated"].as_u64().unwrap(),
        "{}: dated",
        label
    );
    assert_eq!(
        d.metadata.seq_len as u64,
        g["seq_len"].as_u64().unwrap(),
        "{}: L",
        label
    );

    // no edge of any kind touches the undated sequence
    for e in &d.edges {
        assert!(
            e.source != undated && e.target != undated,
            "{}: edge {:?} touches the undated sequence",
            label,
            (&e.source, &e.target, &e.status)
        );
    }

    let want: BTreeSet<Pair> = g["supported_edges"]
        .as_array()
        .unwrap()
        .iter()
        .map(|e| pair(e["id1"].as_str().unwrap(), e["id2"].as_str().unwrap()))
        .collect();
    let got: BTreeSet<Pair> = d
        .edges
        .iter()
        .filter(|e| e.status == "supported_transmission")
        .map(|e| pair(&e.source, &e.target))
        .collect();
    assert_eq!(got, want, "{}: supported edge set", label);

    assert_eq!(
        dossier_partition(d, |n| n.cluster_id_supported),
        partition(&g["danno_partition"]),
        "{}: DANNO partition",
        label
    );
    let want_static = partition(&g["static_partition_on_dated_subset"]);
    assert_eq!(
        dossier_partition(d, |n| n.cluster_id_static),
        want_static,
        "{}: static partition on the dated subset",
        label
    );
    let s = &d.kpi.static_network;
    assert_eq!(
        s.total_clusters,
        want_static.len(),
        "{}: static clusters",
        label
    );
    assert_eq!(
        s.clustered_individuals,
        want_static.iter().map(|c| c.len()).sum::<usize>(),
        "{}: static clustered",
        label
    );
    assert_eq!(
        s.max_cluster_size,
        want_static.iter().map(|c| c.len()).max().unwrap(),
        "{}: static giant",
        label
    );

    let c = &g["chin"];
    let ap = d
        .macro_scaling
        .active_population
        .as_ref()
        .expect("N_act estimable");
    let wa = &c["active_population"];
    for (name, gv) in [
        ("N_act", ap.n_act),
        ("ci_lower", ap.ci_lower),
        ("ci_upper", ap.ci_upper),
    ] {
        let wv = wa[name].as_f64().unwrap();
        assert!(
            rel_close(gv, wv, EXACT_REL_TOL),
            "{}: CHIN {} rust {} python {}",
            label,
            name,
            gv,
            wv
        );
    }
    let theta = d.macro_scaling.composite_parameter_theta;
    assert!(
        rel_close(theta, c["theta"].as_f64().unwrap(), EXACT_REL_TOL),
        "{}: theta {}",
        label,
        theta
    );
    let rho = d
        .macro_scaling
        .surveillance_coverage_rho
        .expect("rho estimable");
    assert!(
        rel_close(rho, c["rho"].as_f64().unwrap(), EXACT_REL_TOL),
        "{}: rho {}",
        label,
        rho
    );
}

#[test]
fn undated_parity_golden_distance_matrix() {
    let aln = Alignment::from_fasta_str(FASTA).unwrap();
    let n = aln.num_sequences();
    let d = run_trace50_with_matrix(&aln, &config(), Some(golden_matrix(n))).unwrap();
    assert_matches("--distances (golden tn93)", &d);
}

#[test]
fn undated_parity_internal_tn93() {
    let aln = Alignment::from_fasta_str(FASTA).unwrap();
    let d = run_trace50(&aln, &config()).unwrap();
    assert_matches("internal TN93", &d);
}
